export const KRUSTY_SAFEGUARD_IDS = Object.freeze(Object.keys(CONTENT));

export function krustySafeguardContent(definitionId, status) {
  if (typeof definitionId !== 'string' || !Object.hasOwn(CONTENT, definitionId)) {
    throw new Error(`No content for supported CIS IG3 safeguard: ${String(definitionId)}`);
  }
  if (status !== 'addressed') {
    throw new Error(`Krusty ${definitionId} requires addressed content, not ${String(status)}`);
  }
  const row = CONTENT[definitionId];
  const [owner_role, process_owner_role] = OWNERS[definitionId.split('.')[0]];
  return {
    scope: row.scope,
    current_implementation: row.current_implementation,
    technology_process: row.technology_process,
    assessment_notes: row.assessment_notes,
    owner_role,
    process_owner_role,
    evidence_check: row.evidence_check,
    remediation: '',
    assessment_plan: '',
  };
}
